def kites_active(flags, end):
    """Return indices of active flags in the first end positions. Active flags are True or the string on."""
    return [i for i,x in enumerate(flags[:end]) if x is True or x == 'on']

def kites_window(seq, left, right):
    """Return entries whose zero-based indices are between left and right inclusive. Indices are nonnegative."""
    return seq[left:right+1]
